//! Owner lock segment only; no global Portal or purchase authority.
#![allow(dead_code)]
#[path = "../../support/rust-postgres.rs"] mod fixture;
use erpx_customer_authority_server::public::portal_commerce_locks::lock_portal_customer_authority_sources;
use erpx_platform_runtime_server::public::postgres::{MigrationTrack,load_migrations,migrate_database};
use sqlx::Connection;
#[tokio::test]
async fn fence_waits_for_real_writer_before_snapshot(){fixture::with_database(4,|pool|async move{
 let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../migrations/postgres");let files=load_migrations(root,MigrationTrack::HoldingWrite).await.unwrap();migrate_database(&pool,MigrationTrack::HoldingWrite,&files).await.unwrap();
 sqlx::raw_sql("INSERT INTO organization_nodes(id,kind,slug,display_name,parent_id,company_id,status,hierarchy_revision) VALUES('company','company','company','Company',NULL,'company','active',1),('branch','branch','branch','Branch','company','company','active',1); INSERT INTO finance_parties(id,company_id,kind,code,name,currency,status,version,created_at,updated_at) VALUES('party','company','customer','C1','Original','THB','active',1,0,0); INSERT INTO commerce_products(id,company_id,sku,name,price_minor) VALUES('product','company','P1','Product',100); INSERT INTO commerce_orders(id,company_id,branch_id,kind,number,party_id,currency,order_date,due_date,note,state,subtotal_minor,tax_minor,version,created_by,created_at,updated_at) VALUES('order','company','branch','sales','SO1','party','THB','2026-01-01','2026-01-01','','confirmed',0,0,1,'user',0,0); INSERT INTO customer_access_bindings(id,company_id,order_id,customer_id,email,expires_at,status,reason,created_by,approved_by,version,created_at,updated_at) VALUES('source','company','order','party','user@example.test',9000000000000,'approved','Original','user','reviewer',1,0,0)").execute(pool.raw()).await.unwrap();let mut c=pool.raw().acquire().await.unwrap();assert!(lock_portal_customer_authority_sources(&mut c).await.is_err());drop(c);
 let mut writer=pool.raw().begin().await.unwrap();let wp:i32=sqlx::query_scalar("SELECT pg_backend_pid()").fetch_one(&mut *writer).await.unwrap();sqlx::query("UPDATE customer_access_bindings SET reason='Committed' WHERE id='source'").execute(&mut *writer).await.unwrap();
 let other=pool.clone();let (send,recv)=tokio::sync::oneshot::channel();let reader=tokio::spawn(async move{let mut c=other.raw().acquire().await.unwrap();let pid:i32=sqlx::query_scalar("SELECT pg_backend_pid()").fetch_one(&mut *c).await.unwrap();send.send(pid).unwrap();let mut tx=c.begin_with("BEGIN ISOLATION LEVEL SERIALIZABLE").await.unwrap();lock_portal_customer_authority_sources(&mut tx).await.unwrap();let n:i64=sqlx::query_scalar("SELECT count(*) FROM pg_locks WHERE pid=pg_backend_pid() AND granted AND mode='ShareRowExclusiveLock' AND relation=ANY(ARRAY['customer_access_bindings'::regclass,'customer_access_events'::regclass,'customer_access_identities'::regclass,'customer_access_reads'::regclass])").fetch_one(&mut *tx).await.unwrap();assert_eq!(n,4); let value:String=sqlx::query_scalar("SELECT reason FROM customer_access_bindings WHERE id='source'").fetch_one(&mut *tx).await.unwrap();tx.rollback().await.unwrap();value});
 let pid=recv.await.unwrap();let mut blocked=false;for _ in 0..200{blocked=sqlx::query_scalar("SELECT $1=ANY(pg_blocking_pids($2))").bind(wp).bind(pid).fetch_one(pool.raw()).await.unwrap();if blocked{break;}tokio::time::sleep(std::time::Duration::from_millis(10)).await;}assert!(blocked,"owner fence must wait for writer");writer.commit().await.unwrap();assert_eq!(tokio::time::timeout(std::time::Duration::from_secs(5),reader).await.unwrap().unwrap(),"Committed");
}).await;}
